import pandas as pd
import matplotlib.pyplot as plt
import numpy as np

def generate_plots():
    try:
        # Load the output generated by the C++ engine
        df = pd.read_csv('mertens_drift_high_res.csv')
        print("[SUCCESS] Loaded mertens_drift_high_res.csv successfully.")
    except FileNotFoundError:
        print("[ERROR] 'mertens_drift_high_res.csv' not found. Please run the compiled C++ engine first.")
        return

    plt.figure(figsize=(11, 6))
    plt.plot(df['Prime'], df['Std_Drift'], color='#e63946', label='Standard Drift (Uncalibrated)', alpha=0.8)
    plt.plot(df['Prime'], df['Opt_Drift'], color='#2a9d8f', label='Optimized Drift (Active Cancellation)', linewidth=2)
    plt.plot(df['Prime'], df['Spectral_Bound'], color='#457b9d', linestyle='--', label='Spectral Boundary Curve (sqrt(p))')
    
    plt.title('Mertens Drift Suppression via 4D Gauge-Orbit Interference', fontsize=14, fontweight='bold')
    plt.xlabel('Prime Number Coordinate Index (p)', fontsize=11)
    plt.ylabel('Cumulative Geometric Displacement', fontsize=11)
    plt.legend(loc='upper left')
    plt.grid(True, alpha=0.3)
    
    output_img = 'drift_suppression_analysis.png'
    plt.savefig(output_img, dpi=300, bbox_inches='tight')
    print(f"[SUCCESS] Visual validation plot saved as: {output_img}")

if __name__ == '__main__':
    generate_plots()
